\label{regularlem}
Let system \eqref{ODEequation} be a $C$-cooperative system. Then there exists $\delta >0$ with the following property: If $\parallel F(z)-G(z)\parallel+\parallel DF(z)-DG(z)\parallel<\delta$ for all $z\in O$, and $W$ is positively invariant under the flow $\psi_{t}$ generated by $G$, then there exists $t_{*}>0$ such that
the matrix $U_{G}^{pq}(t)$ satisfies $U_{G}^{pq}(t)[C\backslash \{0\}]\subset \text{Int }C$ for any $p,q\in W$ and $t\geq t_*$.

Pick $t_*>0$, we consider the matrices $$A_{G}^{pq}(t)=\int^{1}_{0}DG(s\psi_t(p)+(1-s)\psi_t(q))ds$$ and the solution $U_{G}^{pq}(t)$ of
\begin{equation}\label{perturbed-difference-equation}
\begin{cases}
\frac{d}{dt}U = A_{G}^{pq}(t) U \\
U(0)=I,
\end{cases}
\end{equation}
for any $p,q\in W$.

We first prove the positiveness of $U_{G}^{pq}(t)$ for $t\in [t_*, 2t_*]$, i.e., $U_{G}^{pq}(t)[C\backslash \{0\}]\subset \text{Int }C$ for $t\in [t_*, 2t_*]$. Since system \eqref{ODEequation} is $C$-cooperative, there exists a $\delta_{1}>0$ such that $B_{\delta_{1}}(U_{F}^{pq}(t)v)\subset \text{Int }C$ for all $v\in C\backslash \{0\}$ with $|v|=1$. A positive $\delta$ can be found such that if $\parallel F(z)-G(z)\parallel +\parallel DF(z)-DG(z)\parallel<\delta$ then $\parallel U_{F}^{pq}(t)-U_{G}^{pq}(t) \parallel \leq \frac{\delta_{1}}{2}$ hold for $t\in [t_{*},2t_{*}]$.

In fact, by the definition of flow, we have
\begin{equation*}
\begin{cases}
\frac{d}{dt}\phi_{t}(z) = F(\phi_{t}(z)),\\
\frac{d}{dt}\psi_{t}(z) = G(\psi_{t}(z)).
\end{cases}
\end{equation*}
Then,
\begin{align*}
\parallel \phi_{t}(z)-\psi_{t}(z)\parallel & \leq \int^{t}_{0}\parallel F(\phi_{s}(z))-G(\psi_{s}(z))\parallel ds \\ & \leq \int^{t}_{0} \parallel F(\phi_{s}(z))-F(\psi_{s}(z))\parallel ds + \int^{t}_{0} \parallel F(\psi_{s}(z))-G(\psi_{s}(z)) \parallel ds.
\end{align*}
Since $F$ and $G$ are $C^{1}$ and $t_{*} \leq t \leq 2t_{*}$, there exists some $M > 0$ such that $\parallel F(\phi_{s}(z))-F(\psi_{s}(z))\parallel \leq M \parallel \phi_{s}(z)-\psi_{s}(z)\parallel$. Then $\parallel \phi_{t}(z)-\psi_{t}(z)\parallel \leq \int^{t}_{0}M \parallel \phi_{s}(z)-\psi_{s}(z)\parallel ds + \delta t$.

Using the Gronwall's inequality, we obtain
\begin{equation*}
\parallel \phi_{t}(z)-\psi_{t}(z)\parallel \leq \delta 2t_{*} e^{M2t_{*}}.
\end{equation*}
Hence, for $s\in [0,1]$,
\begin{align*}
&\ \ \ \ \parallel [s\phi_{t}(p)+(1-s)\phi_{t}(q)]-[s\psi_{t}(p)+(1-s)\psi_{t}(q)]\parallel

\\ & \leq s\parallel \phi_{t}(p)-\psi_{t}(p)\parallel+ (1-s)\parallel \phi_{t}(q)-\psi_{t}(q)\parallel\\ & \leq s\delta 2t_{*} e^{M2t_{*}}+ (1-s)\delta 2t_{*} e^{M2t_{*}} =  \delta 2t_{*} e^{M2t_{*}}.
\end{align*}
Note that $U_{F}^{pq}(t)$ and $U_{G}^{pq}(t)$ are the solutions of \eqref{difference-equation} and \eqref{perturbed-difference-equation}, respectively,                                                                                                                            
then
\begin{align*}
\parallel U_{F}^{pq}(t)-U_{G}^{pq}(t) \parallel \leq & \int^{t}_{0} \parallel  A_{F}^{pq}(s)U_{F}^{pq}(s)-A_{G}^{pq}(s)U_{G}^{pq}(s) \parallel ds

\\ \leq & \int^{t}_{0} \parallel A_{F}^{pq}(s) \parallel \parallel U_{F}^{pq}(s)-U_{G}^{pq}(s)\parallel ds \\ & +\int^{t}_{0} \parallel A_{F}^{pq}(s)-A_{G}^{pq}(s) \parallel \parallel U_{G}^{pq}(s) \parallel ds.
\end{align*}
Using the Gronwall's inequality again, it follows that
\begin{equation*}
\parallel U_{F}^{pq}(t)-U_{G}^{pq}(t) \parallel \leq e^{\int^{t}_{0} \parallel A_{F}^{pq}(s) \parallel ds} \int^{t}_{0} \parallel A_{F}^{pq}(s)-A_{G}^{pq}(s) \parallel \parallel U_{G}^{pq}(s) \parallel ds.
\end{equation*}
There exist $N>0$ and $L>0$ such that $\parallel U_{G}^{pq}(s) \parallel \leq N$ and $\parallel A_{F}^{pq}(s) \parallel \leq L$ for all $t\in [t_*, 2t_*]$.
Meanwhile,
\begin{align*}
\parallel A_{F}^{pq}(t)-A_{G}^{pq}(t)\parallel \leq & \int^{1}_{0}\parallel DF(s\phi_t(p)+(1-s)\phi_t(q))-DG(s\psi_t(p)+(1-s)\psi_t(q))\parallel ds \\ \leq & \int^{1}_{0}\parallel DF(s\phi_{t}(p)+(1-s)\phi_{t}(q))-DF(s\psi_{t}(p)+(1-s)\psi_{t}(q))\parallel \\ & +\parallel DF(s\psi_{t}(p)+(1-s)\psi_{t}(q))-DG(s\psi_{t}(p)+(1-s)\psi_{t}(q))\parallel ds\\ \leq & \int^{1}_{0} \parallel DF(s\phi_{t}(p)+(1-s)\phi_{t}(q))-DF(s\psi_{t}(p)+(1-s)\psi_{t}(q))\parallel ds+ \delta.
\end{align*}


Since $F$ is $C^{1}$ and $\parallel [s\phi_{t}(p)+(1-s)\phi_{t}(q)]-[s\psi_{t}(p)+(1-s)\psi_{t}(q)]\parallel \leq \delta 2t_{*} e^{M2t_{*}}$, one can choose $\delta < \frac{1}{2}\cdot \frac{\delta_{1}}{2}\cdot \frac{1}{2Nt_{*}e^{2t_{*}L}}$ small enough such that $\parallel DF(s\phi_{t}(p)+(1-s)\phi_{t}(q))-DF(s\psi_{t}(p)+(1-s)\psi_{t}(q))\parallel < \frac{1}{2}\cdot \frac{\delta_{1}}{2}\cdot \frac{1}{2Nt_{*}e^{2t_{*}L}}$. So, $\parallel A_{F}^{pq}(t)-A_{G}^{pq}(t)\parallel \leq \frac{\delta_{1}}{2}\cdot \frac{1}{2Nt_{*}e^{2t_{*}L}}$, which implies that $\parallel U_{F}^{pq}(t)-U_{G}^{pq}(t) \parallel \leq \frac{\delta_{1}}{2}$.
Thus, we obtain that $U_{G}^{pq}(t)[C\backslash \{0\}]\subset \text{Int }C$ for $t\in [t_{*},2t_{*}]$ and $p,q\in W$.

For $t>2t_*$, let us write $t=t_0+kt_*$ with $t_0\in [t_*,2t_*)$. Define $t_j=jt_*$, $p_j=\psi_{t_j}(p)$, $q_j=\psi_{t_j}(q)$ with $j=1,2,\cdots,k$. It is clear that $p_j, q_j\in W$ if $W$ is positively invariant. Since $\psi_{t}(p)-\psi_{t}(q)=U_{G}^{pq}(t)(p-q)$, we obtain that
\begin{equation*}
U_{G}^{pq}(t)=U_{G}^{p_kq_k}(t_0)U_{G}^{p_{k-1}q_{k-1}}(t_*)\cdots U_{G}^{p_1q_1}(t_*)U_{G}^{pq}(t_*).
\end{equation*}
By the preceding proof, $U_{G}^{pq}(t)[C\backslash \{0\}]\subset \text{Int }C$ for $t>2t_*$.

Thus, we have proved that the system \eqref{perturbed-equation} is $C$-cooperative for $t\geq t_*$.

\label{singularlemm}
Consider the system
\begin{equation}\label{singularequ}{}
\begin{cases}
\frac{dx}{d\tau}  = \epsilon f(x,y,\epsilon),\\
\frac{dy}{d\tau}  = g(x,y,\epsilon),
\end{cases}
\end{equation}
where $f :\mathbb{R}^{n} \times \mathbb{R}^{m} \times [0,\epsilon_{0}] \rightarrow \mathbb{R}^{n}$ is $C^{r}_{b}$ and
$g :\mathbb{R}^{n} \times \mathbb{R}^{m} \times [0,\epsilon_{0}] \rightarrow \mathbb{R}^{m}$ is $C^{r}_{b}$. For $x\in \mathbb{R}^{n}$, there is a $C^{r}_{b}$ function $\overline{h} :\mathbb{R}^{n} \rightarrow \mathbb{R}^{m}$ such that $g(x,\overline{h}(x),0)=0$. And there exists a positive constant $\mu$ such that all eigenvalues of the matrix $D_{y}g(x,\overline{h}(x),0)$ have negative real parts less than $-\mu$ for every $x \in \mathbb{R}^{n}$.

Then, there exists a positive number $\epsilon_{1} < \epsilon_{0}$ such that for every $\epsilon \in (0,\epsilon_{1}]$:
\begin{enumerate}[$1)$]
\item
There exists a $C_{b}^{r-1}$ function $h : \mathbb{R}^{n} \times [0,\epsilon_{1}] \rightarrow \mathbb{R}^{m}$
such that the set $\mathbb{C}_{\epsilon}$ defined by
\begin{equation*}
\mathbb{C}_{\epsilon} = \{ (x,h(x,\epsilon)) : x \in \mathbb{R}^{n} \},\  \epsilon \in (0,\epsilon_{1}]
\end{equation*}
is invariant under the flow generated by \eqref{singularequ} and
\begin{equation*}
\underset{x \in \mathbb{R}^{n}}{\sup} \{| h(x,\epsilon) - \overline {h}(x)| : x \in \mathbb{R}^{n} \} \sim O(\epsilon), as \ \epsilon \rightarrow 0.
\end{equation*}
In particular, we have $h(x,0) = \overline {h}(x)$ for all $x \in \mathbb{R}^{n}$.


\item
There is an $(n + m)$-dimensional $C^{r-1}$ submanifold $W^{s}(\mathbb{C}_{\epsilon})$. It is characterized by
\begin{equation*}
W^{s}(\mathbb{C}_{\epsilon}) = \{ (x_{0},y_{0}) : \underset {\tau \geq 0}{\sup} | y(\tau;x_{0},y_{0})-h_{\epsilon}(x(\tau;x_{0},y_{0})) | e^{\frac{\mu \tau}{4}} < \infty \},
\end{equation*}
where $(x(\tau;x_{0},y_{0}),y(\tau;x_{0},y_{0}))$ is the solution of \eqref{singularequ} passing through $(x_{0},y_{0})$ and $h_{\epsilon}(x)=h(x,\epsilon)$ is the function defining $\mathbb{C}_{\epsilon}$.


\item
The manifold $W^{s}(\mathbb{C}_{\epsilon})$ is a disjoint union of the $m$-dimensional $C^{r-1}$ manifold $W^{s}(\xi)$:

\begin{equation*}
W^{s}(\mathbb{C}_{\epsilon}) = \underset{\xi \in \mathbb{R}^{n}}{\cup} W^{s}(\xi).
\end{equation*}

Moreover, $W^{s}(\xi)$ is characterized as
\begin{equation*}
W^{s}(\xi)= \{ (x_{0},y_{0}) : \underset{\tau \geq 0}{\sup} | \widetilde{x}(\tau) | e^{\frac{\mu\tau}{4}} < \infty,\ \underset{\tau \geq 0}{\sup} | \widetilde{y}(\tau) | e^{\frac{\mu\tau}{4}} < \infty \},
\end{equation*}
where $\widetilde{x}(\tau)=x(\tau;x_{0},y_{0})- H_{\epsilon}(\xi)(\tau)$, $\widetilde{y}(\tau)=y(\tau;x_{0},y_{0})- h_{\epsilon}(H_{\epsilon}(\xi)(\tau))$, where $H_{\epsilon}(\xi)(\tau)$ stands for a unique solution of $\frac{dx}{d\tau}=\epsilon f(x,h_{\epsilon}(x),\epsilon)$, $x(0)= \xi \in \mathbb{R}^{n}$.



\item
There is a constant $\delta_{0} > 0$ such that if a solution $(x(\tau),y(\tau))$ of \eqref{singularequ} satisfies
\begin{equation*}
\underset {\tau \geq 0}{\sup} | y(\tau) - h_{\epsilon}(x(\tau)) | < \delta_{0},
\end{equation*}
then $(x(0),y(0)) \in W^{s}(\mathbb{C}_{\epsilon})$.


\item
The fibers are positively invariant in the sense that
\begin{equation*}
W^{s}(H_{\epsilon}(\xi)(\tau)) = \{ (x(\tau;,x_{0},y_{0}),y(\tau;x_{0},y_{0})) : (x_{0},y_{0}) \in W^{s}(\xi) \},
\end{equation*}
for each $\tau \geq 0$.


\item
The fibers restricted to the $\delta_{0}$ neighborhood of $\mathbb{C}_{\epsilon}$, denoted by $W^{s}_{\epsilon, \delta_{0}}$, can be parameterized as follows. Let $L_{\delta_{0}}=\{ z\in \mathbb{R}^{m} : |z|\leq \delta_{0} \}$. There are two $C^{r-1}_{b}$ functions
\begin{equation*}
P_{\epsilon, \delta_{0}} : \mathbb{R}^{n} \times L_{\delta_{0}} \rightarrow \mathbb{R}^{n},
\end{equation*}
\begin{equation*}
Q_{\epsilon, \delta_{0}} : \mathbb{R}^{n} \times L_{\delta_{0}} \rightarrow \mathbb{R}^{m},
\end{equation*}
and a map
\begin{equation*}
T_{\epsilon, \delta_{0}} : \mathbb{R}^{n} \times L_{\delta_{0}} \rightarrow \mathbb{R}^{n} \times \mathbb{R}^{m}
\end{equation*}
mapping $(\xi, \eta)$ to $(x,y)$, where
\begin{equation*}
x = \xi + P_{\epsilon, \delta_{0}}(\xi, \eta), \ y = h(x, \epsilon) + Q_{\epsilon, \delta_{0}}(\xi, \eta),
\end{equation*}
such that
\begin{equation*}
W^{s}_{\epsilon, \delta_{0}}(\xi) = T_{\epsilon, \delta_{0}}(\xi, L_{\delta_{0}}).
\end{equation*}
\end{enumerate}

\label{singularrmk}

\begin{enumerate}[(1)]
\item
The $\delta_{0}$ in property 4) of Lemma \ref{singularlemm} can be chosen uniformly for $\epsilon \in (0,\epsilon_{0}]$.

\item
The property 3) of Lemma \ref{singularlemm} is often referred to as the asymptotic phase property in the way
\begin{equation*}
| x(\tau;x_{0},y_{0}) - H_{\epsilon}(\xi)(\tau) | \rightarrow 0,
\end{equation*}
\begin{equation*}
| y(\tau;x_{0},y_{0}) - h_{\epsilon}(H_{\epsilon}(\xi)(\tau) | \rightarrow 0,
\end{equation*}
as $\tau \rightarrow \infty$.
\end{enumerate}
